{"name": "create_salary_alerts_table", "query": "
-- ============================================================
-- Support tables: salary_alerts & monthly_reports
-- ============================================================

-- salary_alerts: stores high-salary notification events
CREATE TABLE IF NOT EXISTS employees.salary_alerts (
    alert_id       BIGSERIAL    PRIMARY KEY,
    employee_id    BIGINT       NOT NULL REFERENCES employees.employee(id),
    salary_amount  BIGINT       NOT NULL,
    alert_date     DATE         NOT NULL DEFAULT CURRENT_DATE,
    status         VARCHAR(20)  NOT NULL DEFAULT 'new',
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE  employees.salary_alerts IS 'Auto-generated alerts when a salary record exceeds $120,000';
COMMENT ON COLUMN employees.salary_alerts.status IS 'Lifecycle state: new | acknowledged | resolved';
"}

{"name": "create_monthly_reports_table", "query": "
-- monthly_reports: one record per generated report run
CREATE TABLE IF NOT EXISTS employees.monthly_reports (
    report_id         BIGSERIAL     PRIMARY KEY,
    report_date       DATE          NOT NULL,
    department_count  INTEGER       NOT NULL,
    total_employees   INTEGER       NOT NULL,
    avg_salary        DECIMAL(12,2) NOT NULL,
    generated_at      TIMESTAMPTZ   NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE  employees.monthly_reports IS 'Executive monthly snapshots produced by generate_monthly_report()';
COMMENT ON COLUMN employees.monthly_reports.report_date      IS 'Logical report period start date (passed by caller)';
COMMENT ON COLUMN employees.monthly_reports.total_employees  IS 'Current active headcount at time of generation';
COMMENT ON COLUMN employees.monthly_reports.avg_salary       IS 'Current average salary at time of generation';
"}

{"name": "refresh_all_materialized_views", "query": "
-- ============================================================
-- REFRESH all executive materialized views
-- Using CONCURRENTLY because unique indexes exist on each view
-- ============================================================
REFRESH MATERIALIZED VIEW CONCURRENTLY employees.exec_department_summary;
REFRESH MATERIALIZED VIEW CONCURRENTLY employees.exec_hiring_trends;
REFRESH MATERIALIZED VIEW CONCURRENTLY employees.exec_salary_distribution;
"}

{"query": "
-- Call the procedure and capture the returned report_id
DO $$
DECLARE
    v_report_id BIGINT;
BEGIN
    CALL employees.generate_monthly_report('2024-01-01', v_report_id);
    RAISE NOTICE 'generate_monthly_report returned report_id = %', v_report_id;
END;
$$;
"}

